// BAD:
for (int tile_i = 0; tile_i < N; tile_i += TILE_SIZE) {
#pragma HLS DATAFLOW
    ...
}
// GOOD:
for (int tile = 0; tile < NUM_TILES; tile++) {
    const int tile_i = tile * TILE_SIZE;
    process_tile_lcs(A, b, y, tile_i);  // helper contains DATAFLOW + 3 calls
}

// BAD: t-loop inside DATAFLOW with alternating writers on local_A
#pragma HLS DATAFLOW
load(...);
for (int t = 0; t < TSTEPS; t++) {
    compute_B(local_A, local_B);
    compute_A(local_B, local_A);  // HLS 200-979
}
store(...);

// GOOD: one compute task owns the t-loop
#pragma HLS DATAFLOW
load(..., local_A);
compute_timesteps(local_A, local_B, local_A_new);
store(..., local_B);

OVERLAP REPORT (required if DATAFLOW kept):
| stage pairing | overlap? | evidence (stream / gmemN / schedule) |

// BAD: tasks share locals only, one gmem bundle
#pragma HLS DATAFLOW
load_all(...);   // writes shared local_A
compute_all(...); // reads same local_A — no stream, no overlap proof

// GOOD: streams between tasks OR distinct gmemN + proven concurrent schedule
#pragma HLS DATAFLOW
hls::stream<tile_t> q;
load_tile(A, q, tile_i);
compute_tile(q, out_q);
store_tile(out_q, y, tile_i);

// BAD: fake ping-pong — still serial per tile
for (int tile = 0; tile < NUM_TILES; tile++) {
    load_tile(A, buf[tile & 1], tile);
    compute_tile(buf[tile & 1], out_buf[tile & 1]);
    store_tile(out_buf[tile & 1], A, tile);
}
// GOOD without overlap: single local buffer + pipelined loops
// GOOD with overlap: DATAFLOW helper where load(t+1) || compute(t) || store(t-1)

// BAD: tile loop inside DATAFLOW — parallel A readers
#pragma HLS DATAFLOW
for (int i0 = 0; i0 < N; i0 += TILE_SIZE) {
    load_tile_A(A, local_A, i0);  // HLS 200-1013 on gmem for A
    compute_tile(...);
}

// GOOD: fused load once, or stream pipeline
#pragma HLS DATAFLOW
fused_load_all_inputs(...);   // single reader per port
compute_all_tiles(...);       // locals only
fused_store_all_outputs(...);

// FORBIDDEN when A/x/w are m_axi ports:
//   A[i][j] = A[i][j] + expr;
//   x[i] = x[i] + expr;
// GOOD: load -> local acc/buffer -> single store
//   double acc = x_local[i];
//   for (int j = 0; j < N; j++) acc += beta * A_local[j][i] * y_local[j];
//   x_local[i] = acc;
//   x[i] = x_local[i];  // one write per element

// GOOD canonical DATAFLOW:
#pragma HLS DATAFLOW
hls::stream<tile_t> load_to_compute;
load_tile(A, load_to_compute, tile_i);
compute_tile(load_to_compute, compute_to_store);
store_tile(compute_to_store, A, tile_i);

// Triangular/pivot-dependent tiles often depend on prior rows/columns
// BAD: ping-pong across tiles without dependence proof
// GOOD: sequential tiles; optional DATAFLOW only inside one tile:
void process_tile_lcs(...) {
#pragma HLS DATAFLOW
    load_tile(...);
    compute_tile(...);
    store_tile(...);
}
